/**
 * @fileoverview Unit tests for the generated pricing table and the cost helpers.
 *
 * The table itself is machine-generated by `scripts/refresh-pricing.mjs` from
 * `GET /model/info` — these tests check the MECHANISM, not hand-typed rates.
 * The one thing they do assert about the numbers is that every entry is
 * present and positive, which catches a truncated regeneration.
 */

import {
	MODEL_PRICING,
	MODEL_PRICING_AS_OF,
	MODEL_ALIASES,
	MODEL_INFO,
	DEFAULT_MODEL,
	resolvePricing,
	computeCost,
	listModels,
	getModelInfo,
	canonicalModelId,
	budgetTokensToEffort
} from '../../models.js';

describe('the generated table', () => {
	it('is stamped with a generation date', () => {
		expect(MODEL_PRICING_AS_OF).toMatch(/^\d{4}-\d{2}-\d{2}$/);
	});

	it('prices every model it lists, with positive rates', () => {
		const ids = listModels({ includeIntegration: true });
		expect(ids.length).toBeGreaterThan(15);
		for (const id of ids) {
			const p = MODEL_PRICING[id];
			expect(p).toBeDefined();
			expect(p.input).toBeGreaterThan(0);
			expect(p.output).toBeGreaterThan(0);
		}
	});

	it('carries a capability record for every priced model', () => {
		for (const id of Object.keys(MODEL_PRICING)) {
			expect(MODEL_INFO[id]).toBeDefined();
		}
	});

	it('excludes integration-scoped models from the default listing', () => {
		const plain = listModels();
		const all = listModels({ includeIntegration: true });
		expect(all.length).toBeGreaterThan(plain.length);
		for (const id of all.filter(i => !plain.includes(i))) {
			expect(MODEL_INFO[id].lifecycle).toBe('integration');
		}
	});

	it('serves the default model', () => {
		expect(MODEL_PRICING[DEFAULT_MODEL]).toBeDefined();
		expect(DEFAULT_MODEL).toBe('claude-sonnet-5');
	});
});

describe('resolvePricing()', () => {
	it('returns the rate plus the asOf stamp', () => {
		const p = resolvePricing('claude-sonnet-5');
		expect(p).not.toBeNull();
		expect(p.asOf).toBe(MODEL_PRICING_AS_OF);
	});

	it('follows an alias', () => {
		expect(resolvePricing('claude-sonnet-4-6')).toEqual(resolvePricing('claude-sonnet-5'));
		expect(canonicalModelId('gemini-3.6-flash')).toBe('gemini-3.8-flash');
	});

	it('returns null for an unknown model — UNKNOWN, not free', () => {
		expect(resolvePricing('no-such-model')).toBeNull();
		expect(resolvePricing(null)).toBeNull();
		expect(resolvePricing(undefined)).toBeNull();
	});

	it('honours a date-windowed intro rate', () => {
		const entry = {
			input: 10, output: 50,
			intro: { input: 1, output: 5, until: '2026-12-31' }
		};
		MODEL_PRICING['__test-intro'] = entry;
		try {
			const inside = resolvePricing('__test-intro', { at: '2026-06-01' });
			expect(inside.input).toBe(1);
			expect(inside.introUntil).toBe('2026-12-31');

			const after = resolvePricing('__test-intro', { at: '2027-01-02' });
			expect(after.input).toBe(10);
			expect(after.introUntil).toBeUndefined();

			// The last day of the window is inclusive.
			expect(resolvePricing('__test-intro', { at: '2026-12-31T18:00:00Z' }).input).toBe(1);
		} finally {
			delete MODEL_PRICING['__test-intro'];
		}
	});
});

describe('computeCost()', () => {
	it('bills input and output at the table rate', () => {
		// claude-sonnet-5: $2 in / $10 out per 1M
		const cost = computeCost({ promptTokens: 1_000_000, responseTokens: 1_000_000 }, 'claude-sonnet-5');
		expect(cost).toBeCloseTo(12, 6);
	});

	it('bills reasoning tokens at the output rate', () => {
		const withThoughts = computeCost({ promptTokens: 0, responseTokens: 0, thoughtsTokens: 1_000_000 }, 'claude-sonnet-5');
		expect(withThoughts).toBeCloseTo(10, 6);
	});

	it('reads the model from the usage object when none is passed', () => {
		const cost = computeCost({ promptTokens: 1_000_000, responseTokens: 0, requestedModel: 'claude-haiku-4-5' });
		expect(cost).toBeCloseTo(1, 6);
	});

	it('accepts the ak-claude / ak-gemini positional signature', () => {
		expect(computeCost('claude-sonnet-5', 1_000_000, 1_000_000)).toBeCloseTo(12, 6);
		// third positional is ak-gemini's thoughtsTokens
		expect(computeCost('claude-sonnet-5', 0, 0, 1_000_000)).toBeCloseTo(10, 6);
	});

	it('returns null — not 0 — when pricing is unknown', () => {
		expect(computeCost({ promptTokens: 10, responseTokens: 10 }, 'no-such-model')).toBeNull();
		expect(computeCost('no-such-model', 10, 10)).toBeNull();
	});
});

describe('getModelInfo()', () => {
	it('reports capabilities and the upstream deployment', () => {
		const info = getModelInfo('claude-sonnet-5');
		expect(info.upstreamModel).toMatch(/claude-sonnet-5/);
		expect(info.supportsFunctionCalling).toBe(true);
		expect(info.maxInputTokens).toBeGreaterThan(0);
	});

	it('follows aliases and nulls the unknown', () => {
		expect(getModelInfo('claude-sonnet-4-6')).toEqual(getModelInfo('claude-sonnet-5'));
		expect(getModelInfo('no-such-model')).toBeNull();
	});

	it('every alias points at a model that exists', () => {
		for (const target of Object.values(MODEL_ALIASES)) {
			expect(MODEL_PRICING[target]).toBeDefined();
		}
	});
});

describe('budgetTokensToEffort()', () => {
	it('maps legacy ak-claude budgets onto effort levels', () => {
		expect(budgetTokensToEffort(0)).toBeNull();
		expect(budgetTokensToEffort(1024)).toBe('low');
		expect(budgetTokensToEffort(8000)).toBe('medium');
		expect(budgetTokensToEffort(16000)).toBe('high');
		expect(budgetTokensToEffort(32000)).toBe('xhigh');
	});
});
